SELECT     TRUNC(SYSDATE)                                       AS \"Report Date\",      im.DEPT                                              AS \"Department Number\",     d.DEPT_NAME                                          AS \"Department Name\",     im.CLASS                                             AS \"Class Number\",     c.CLASS_NAME                                         AS \"Class Name\",     im.SUBCLASS                                          AS \"Subclass Number\",     sc.SUB_NAME                                          AS \"Subclass Name\",      im.ITEM                                              AS \"Item ID\",     im.ITEM_DESC                                         AS \"Item Description\",     im.STANDARD_UOM                                      AS \"Unit of Measure\",     im.PACK_IND                                          AS \"Pack Indicator\",     im.STATUS                                            AS \"Item Status\",      ril.LOCATION                                         AS \"Location ID\",     il.LOC_TYPE                                          AS \"Location Type\",     CASE il.LOC_TYPE         WHEN 'S' THEN 'Store'         WHEN 'W' THEN 'Warehouse'     END                                                  AS \"Location Type Description\",     CASE il.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                  AS \"Location Name\",     il.STATUS                                            AS \"Item Location Status\",     CASE il.STATUS         WHEN 'A' THEN 'Active'         WHEN 'C' THEN 'Discontinued'         WHEN 'I' THEN 'Inactive'         WHEN 'D' THEN 'Delete'     END                                                  AS \"Item Location Status Description\",      ril.REPL_METHOD                                      AS \"Replenishment Method\",     'Floating Point'                                     AS \"Replenishment Method Description\",     ril.STOCK_CAT                                        AS \"Stock Category\",     CASE ril.STOCK_CAT         WHEN 'C' THEN 'Cross-Docked'         WHEN 'D' THEN 'Direct to Store'         WHEN 'L' THEN 'WH/Cross Link'         WHEN 'W' THEN 'Warehouse Stocked'         ELSE ril.STOCK_CAT     END                                                  AS \"Stock Category Description\",      ril.REPL_ORDER_CTRL                                  AS \"Order Control\",     CASE ril.REPL_ORDER_CTRL         WHEN 'A' THEN 'Automatic'         WHEN 'B' THEN 'Buyer Worksheet'         WHEN 'M' THEN 'Manual'         WHEN 'S' THEN 'Semi-Automatic'     END                                                  AS \"Order Control Description\",      ril.MIN_STOCK                                        AS \"Minimum Stock\",     ril.MAX_STOCK                                        AS \"Maximum Stock\",     NVL(ril.MAX_STOCK, 0) - NVL(ril.MIN_STOCK, 0)      AS \"Replenishment Band\",      mra.PRES_STOCK                                       AS \"Presentation Stock\",     ril.DEMO_STOCK                                       AS \"Demo Stock\",      ils.STOCK_ON_HAND                                    AS \"Current Stock on Hand\",     CASE         WHEN ils.STOCK_ON_HAND &lt; NVL(ril.MIN_STOCK, 0)         THEN 'BELOW MIN - REORDER DUE'         WHEN ils.STOCK_ON_HAND BETWEEN              NVL(ril.MIN_STOCK, 0) AND NVL(ril.MAX_STOCK, 0)         THEN 'WITHIN RANGE'         WHEN ils.STOCK_ON_HAND &gt; NVL(ril.MAX_STOCK, 0)         THEN 'ABOVE MAX - OVERSTOCK'         ELSE 'UNKNOWN'     END                                                  AS \"Stock Position\",     GREATEST(NVL(ril.MAX_STOCK, 0) - NVL(ils.STOCK_ON_HAND, 0), 0)                                                          AS \"Implied Recommended Order Quantity\",      ril.PRIMARY_REPL_SUPPLIER                            AS \"Replenishment Supplier ID\",     sp.SUP_NAME                                          AS \"Supplier Name\",     isc.LEAD_TIME                                        AS \"Supplier Lead Time\",     isc.PICKUP_LEAD_TIME                                 AS \"Pickup Lead Time\",      iscl.PICKUP_LEAD_TIME                                AS \"Location Pickup Lead Time Override\",      ril.SUPP_LEAD_TIME                                   AS \"Effective Lead Time\",     ril.PICKUP_LEAD_TIME                                 AS \"Effective Pickup Lead Time\",     ril.ADJ_SUPP_LEAD_TIME                               AS \"Adjusted Supplier Lead Time\",     ril.ADJ_PICKUP_LEAD_TIME                             AS \"Adjusted Pickup Lead Time\",     ril.WH_LEAD_TIME                                     AS \"Warehouse Lead Time\",     ril.SOURCE_WH                                        AS \"Source Warehouse\",      ril.REVIEW_CYCLE                                     AS \"Review Cycle\",     CASE ril.REVIEW_CYCLE         WHEN '0' THEN 'Every Week'         WHEN '1' THEN 'Every Day'         WHEN '2' THEN 'Every 2 Weeks'         WHEN '3' THEN 'Every 3 Weeks'         WHEN '4' THEN 'Every 4 Weeks'         WHEN '5' THEN 'Every 5 Weeks'         WHEN '6' THEN 'Every 6 Weeks'         WHEN '7' THEN 'Every 7 Weeks'         WHEN '8' THEN 'Every 8 Weeks'         ELSE 'Every ' || ril.REVIEW_CYCLE || ' Weeks'     END                                                  AS \"Review Cycle Description\",      mra.MONDAY_IND                                       AS \"Monday Indicator\",     mra.TUESDAY_IND                                      AS \"Tuesday Indicator\",     mra.WEDNESDAY_IND                                    AS \"Wednesday Indicator\",     mra.THURSDAY_IND                                     AS \"Thursday Indicator\",     mra.FRIDAY_IND                                       AS \"Friday Indicator\",     mra.SATURDAY_IND                                     AS \"Saturday Indicator\",     mra.SUNDAY_IND                                       AS \"Sunday Indicator\",      mra.NON_SCALING_IND                                  AS \"Scaling Exempt Indicator\",     mra.MAX_SCALE_VALUE                                  AS \"Maximum Scale Amount\",      mra.MIN_STOCK                                        AS \"Master Minimum Stock\",     mra.MAX_STOCK                                        AS \"Master Maximum Stock\",     mra.PRES_STOCK                                        AS \"Master Presentation Stock\",      CASE WHEN ril.MAX_STOCK IS NULL OR ril.MAX_STOCK = 0          THEN 'WARN: MAX STOCK NOT SET' ELSE 'OK'     END                                                  AS \"Maximum Stock Flag\",     CASE WHEN ril.MIN_STOCK IS NULL OR ril.MIN_STOCK = 0          THEN 'WARN: MIN STOCK NOT SET' ELSE 'OK'     END                                                  AS \"Minimum Stock Flag\",     CASE WHEN ril.PRIMARY_REPL_SUPPLIER IS NULL               AND ril.STOCK_CAT IN ('C','D','L','W')          THEN 'WARN: SUPPLIER MISSING' ELSE 'OK'     END                                                  AS \"Supplier Flag\",     CASE WHEN NVL(isc.PICKUP_LEAD_TIME, 0) = 0               AND ril.STOCK_CAT IN ('C','D','L','W')          THEN 'WARN: PICKUP LEAD TIME MISSING' ELSE 'OK'     END                                                  AS \"Pickup Lead Time Flag\",      CASE         WHEN (ril.MAX_STOCK IS NULL OR ril.MAX_STOCK = 0)           OR (ril.PRIMARY_REPL_SUPPLIER IS NULL               AND ril.STOCK_CAT IN ('C','D','L','W'))           OR (NVL(isc.PICKUP_LEAD_TIME, 0) = 0               AND ril.STOCK_CAT IN ('C','D','L','W'))         THEN 'INCOMPLETE SETUP'         WHEN (ril.MIN_STOCK IS NULL OR ril.MIN_STOCK = 0)         THEN 'REVIEW RECOMMENDED'         ELSE 'FULLY CONFIGURED'     END                                                  AS \"Setup Status\",      ils.UNIT_COST                                        AS \"Unit Cost\",     ils.AV_COST                                          AS \"Weighted Average Cost\",     il.SELLING_UNIT_RETAIL                               AS \"Unit Retail\",      ril.LAST_UPDATE_DATETIME                             AS \"Last Replenishment Update\",     TRUNC(SYSDATE) - TRUNC(ril.LAST_UPDATE_DATETIME)    AS \"Days Since Update\"  FROM     MFCS_RDS.RDS_WV_REPL_ITEM_LOC              ril      JOIN  MFCS_RDS.RDS_WV_ITEM_LOC             il    ON  ril.ITEM          = il.ITEM                                                      AND  ril.LOCATION      = il.LOC     JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER          im    ON  ril.ITEM          = im.ITEM                                                      AND  im.TRAN_LEVEL     = im.ITEM_LEVEL     JOIN  MFCS_RDS.RDS_WV_DEPS                 d     ON  im.DEPT           = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS                c     ON  im.DEPT           = c.DEPT                                                      AND  im.CLASS          = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS             sc    ON  im.DEPT           = sc.DEPT                                                      AND  im.CLASS          = sc.CLASS                                                      AND  im.SUBCLASS       = sc.SUBCLASS      LEFT JOIN MFCS_RDS.RDS_WV_STORE            st    ON  ril.LOCATION      = st.STORE                                                      AND  il.LOC_TYPE       = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH              wh     ON  ril.LOCATION      = wh.WH                                                      AND  il.LOC_TYPE       = 'W'      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH    ils    ON  ril.ITEM          = ils.ITEM                                                      AND  ril.LOCATION      = ils.LOC                                                      AND  ils.LOC_TYPE      = il.LOC_TYPE      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY isc  ON  ril.ITEM          = isc.ITEM                                                      AND  ril.PRIMARY_REPL_SUPPLIER = isc.SUPPLIER                                                      AND  isc.PRIMARY_SUPP_IND      = 'Y'                                                      AND  isc.PRIMARY_COUNTRY_IND   = 'Y'      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY_LOC iscl                                                       ON  ril.ITEM          = iscl.ITEM                                                      AND  ril.PRIMARY_REPL_SUPPLIER = iscl.SUPPLIER                                                      AND  iscl.LOC          = ril.LOCATION      LEFT JOIN MFCS_RDS.RDS_WV_SUPS             sp    ON  ril.PRIMARY_REPL_SUPPLIER = sp.SUPPLIER      LEFT JOIN MFCS_RDS.RDS_WV_MASTER_REPL_ATTR mra   ON  ril.ITEM          = mra.ITEM                                                      AND  ril.LOCATION      = mra.LOCATION WHERE     ril.REPL_METHOD     = 'F'     AND il.STATUS       IN ('A', 'C')     AND im.STATUS        = 'A'  ORDER BY     CASE         WHEN (ril.MAX_STOCK IS NULL OR ril.MAX_STOCK = 0)           OR (ril.PRIMARY_REPL_SUPPLIER IS NULL AND ril.STOCK_CAT IN ('C','D','L','W'))           OR (NVL(isc.PICKUP_LEAD_TIME,0) = 0  AND ril.STOCK_CAT IN ('C','D','L','W'))         THEN 'INCOMPLETE SETUP'         WHEN (ril.MIN_STOCK IS NULL OR ril.MIN_STOCK = 0)         THEN 'REVIEW RECOMMENDED'         ELSE 'FULLY CONFIGURED'     END,     d.DEPT_NAME,     c.CLASS_NAME,     sc.SUB_NAME,     im.ITEM_DESC,     CASE il.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>Report Date</ds:name><ds:datatype>timestamp</ds:datatype></ds:column><ds:column><ds:name>Department Number</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Department Name</ds:name><ds:datatype>varchar(120)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Class Number</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Class Name</ds:name><ds:datatype>varchar(120)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><